import Block from "../Block.js";

// Registered as ruby:ruby_block
export default class BlockRubyBlock extends Block {
    static inventoryTab = "Ruby \"Mod\"";

    constructor(id, textureSlotId) {
        super(id, textureSlotId);
        this.description = "Ruby Block";
        this.hardness = 1.5;
        if (Block.sounds && Block.sounds.glass) this.sound = Block.sounds.glass;
    }

    getTextureForFace(face) {
        return 'ruby:ruby_block';
    }

    getLightValue(world, x, y, z) {
        return 7;
    }

    isTranslucent() {
        return true;
    }

    occludesNeighborFaces() {
        return false;
    }
}

